use std::io::{Read, Result};

fn count_bytes<R: Read>(
    mut r: R,
) -> Result<usize> {
    let mut buf = Vec::new();
    r.read_to_end(&mut buf)?;
    Ok(buf.len())
}

use std::io::{Result, Write};

fn log<W: Write>(
    w: &mut W,
    msg: &str,
) -> Result<()> {
    w.write_all(msg.as_bytes())
}
